import os, glob, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', None)
    if not d:
        return {}
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r[:10]) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Keys found:", list(G.keys()))
for k in G:
    grid = G[k][:5]
    print(f"\n{k}: shape={len(grid)}x{len(grid[0])}")
    for row in grid:
        print(' '.join(f'{x:2d}' for x in row))

